formula.expression:
if(
  !empty({{notion:block_property:QqLw:bc8f39b1-fae7-831f-8f4f-874e4af94d52:ca3f39b1-fae7-8108-bbc1-000316b6e532}}),
  ifs(
    {{notion:block_property:z%5Eip:bc8f39b1-fae7-831f-8f4f-874e4af94d52:ca3f39b1-fae7-8108-bbc1-000316b6e532}}.contains("Transfer"), -toNumber({{notion:block_property:Ov%5D%5D:bc8f39b1-fae7-831f-8f4f-874e4af94d52:ca3f39b1-fae7-8108-bbc1-000316b6e532}}),
    {{notion:block_property:z%5Eip:bc8f39b1-fae7-831f-8f4f-874e4af94d52:ca3f39b1-fae7-8108-bbc1-000316b6e532}}.contains("Credit Card Payment"), - toNumber({{notion:block_property:Ov%5D%5D:bc8f39b1-fae7-831f-8f4f-874e4af94d52:ca3f39b1-fae7-8108-bbc1-000316b6e532}}),
    {{notion:block_property:z%5Eip:bc8f39b1-fae7-831f-8f4f-874e4af94d52:ca3f39b1-fae7-8108-bbc1-000316b6e532}}.contains("Debit Payment"), -toNumber({{notion:block_property:Ov%5D%5D:bc8f39b1-fae7-831f-8f4f-874e4af94d52:ca3f39b1-fae7-8108-bbc1-000316b6e532}}),
   toNumber("")
  ),
 toNumber("")
)

if(
  or(empty({{notion:block_property:OM%3Dh:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}}), not empty({{notion:block_property:nueS:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}})),
  "",
  let(
    pCount, if(empty({{notion:block_property:%3C%3D%3C%60:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}}), 1, {{notion:block_property:%3C%3D%3C%60:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}}),
    if(
      or({{notion:block_property:OM%3Dh:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}} == "Daily", {{notion:block_property:OM%3Dh:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}} == "Weekly"),
      formatDate(
        if(
          {{notion:block_property:OM%3Dh:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}} == "Daily",
          dateAdd({{notion:block_property:t%3DUS:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}}, pCount, "days"),
          dateAdd({{notion:block_property:t%3DUS:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}}, pCount, "weeks")
        ),
        "MMMM DD, YYYY"
      ),
      if(
        {{notion:block_property:OM%3Dh:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}} == "Monthly",
        let(
          bDay, toNumber({{notion:block_property:n%5CQd:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}}.first()),
          dDay, toNumber({{notion:block_property:Cw%3E%3F:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}}.first()),
          pdDay, date({{notion:block_property:t%3DUS:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}}),

          /* Determines if the purchase date missed the current month's billing cycle */
          missedCycle, if(pdDay > bDay, 1, 0),
          billOffset, missedCycle + pCount - 1,

          /* Establishes the base billing date */
          billDate, dateAdd({{notion:block_property:t%3DUS:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}}, billOffset, "months"),

          /* Pushes due date to the next month if Billing Day > Due Day */
          dueOffsetDate, if(bDay > dDay, dateAdd(billDate, 1, "months"), billDate),
          dayStr, if(dDay < 10, "0" + format(dDay), format(dDay)),

          /* Bypasses parseDate to strictly output the exact required string, avoiding rollover issues for days like 31 */
          formatDate(dueOffsetDate, "MMMM ") + dayStr + formatDate(dueOffsetDate, ", YYYY")
        ),
        let(
          targetDate, 
          if(
            {{notion:block_property:OM%3Dh:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}} == "Bi-monthly", dateAdd({{notion:block_property:t%3DUS:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}}, pCount * 2, "months"),
            if({{notion:block_property:OM%3Dh:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}} == "Quarterly", dateAdd({{notion:block_property:t%3DUS:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}}, pCount * 3, "months"),
            if({{notion:block_property:OM%3Dh:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}} == "Semi-annually", dateAdd({{notion:block_property:t%3DUS:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}}, pCount * 6, "months"),
            if({{notion:block_property:OM%3Dh:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}} == "Annually", dateAdd({{notion:block_property:t%3DUS:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}}, pCount, "years"),
            {{notion:block_property:t%3DUS:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}})))
          ),
          dueNum, toNumber({{notion:block_property:Cw%3E%3F:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}}.first()),
          dueDay, if(dueNum < 10, "0" + format(dueNum), format(dueNum)),
          formatDate(targetDate, "MMMM ") + dueDay + formatDate(targetDate, ", YYYY")
        )
      )
    )
  )
)

if(
  not empty({{notion:block_property:%7CPLE:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}}),
  let(
    diff, dateBetween({{notion:block_property:%7CPLE:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}}, {{notion:block_property:t%3DUS:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}}, "days"),
    format(diff) + " " + if(diff == 1, "day", "days") + " after the custom end date"
  ),
  let(
    d, dateBetween(today(), {{notion:block_property:t%3DUS:00df39b1-fae7-8247-925e-87096aed70bd:ca3f39b1-fae7-8108-bbc1-000316b6e532}}, "days"),
    format(d) + " " + if(d == 1, "day", "days") + " after bought date"
  )
)
